using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
using UnityEngine.Rendering;
namespace MassiveArmy.Planetary
{
    [DefaultExecutionOrder(-220)]public sealed class PlanetLandingValidation:MonoBehaviour
    {
        [Serializable]sealed class Report{public string status="PASS",error="";public List<string> checks=new List<string>();public int greenPixels,redPixels;public double hoverDrift,landingError,assistMedianMs,assistP95Ms,previewMedianMs,previewP95Ms;}
        readonly Report report=new Report();PlanetDevelopment world;PlanetSpacecraft ship;string output;RenderTexture target,hud,composite;Material compositeMaterial;GameObject blocker;
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){if(!Application.isEditor&&Array.IndexOf(Environment.GetCommandLineArgs(),"-planet-landing-validation")>=0)new GameObject("Assisted landing validation").AddComponent<PlanetLandingValidation>();}
        void Awake(){var args=Environment.GetCommandLineArgs();output=args[Array.IndexOf(args,"-planet-output")+1];Directory.CreateDirectory(output);world=FindAnyObjectByType<PlanetDevelopment>();world.currentRtsContent=true;world.ambientZombies=0;world.requestedCapacity=8192;world.configuredRadius=120000;Application.targetFrameRate=-1;QualitySettings.vSyncCount=0;}
        void Start(){StartCoroutine(Guard());}
        void Check(bool value,string text){if(!value)throw new InvalidOperationException(text);report.checks.Add(text);}
        IEnumerator Guard(){var run=Run();while(true){object next;try{if(!run.MoveNext())break;next=run.Current;}catch(Exception e){report.status="FAIL";report.error=e.ToString();Debug.LogException(e);break;}yield return next;}File.WriteAllText(Path.Combine(output,"validation.json"),JsonUtility.ToJson(report,true));Application.Quit(report.status=="PASS"?0:1);}
        bool Space(){world.Paused=false;bool result=ship.TryLandingOrTakeoff();world.Paused=true;return result;}
        void FinishTransition(){int steps=0;while(ship.AutoFlightActive&&steps++<1200)ship.Integrate(1f/60,Vector3.one,Vector3.one,true,true);Check(!ship.AutoFlightActive,"Automatic flight finishes within its bounded duration despite manual control inputs");}
        void Place(Vector3 direction,float altitude,Vector3 velocity){var up=direction;var east=Vector3.Cross(Vector3.up,up).normalized;var forward=-up;var surface=new PlanetSurface(world.definition);ship.SetFlightStateForValidation(new SpacePose{position=surface.GetSurfacePositionPrecise(up,altitude),rotation=Quaternion.LookRotation(forward,east),linearVelocity=new Double3(velocity)});ship.Rebase();Physics.SyncTransforms();ship.RefreshLandingPreview(true);}
        GameObject Cube(Double3 body,Quaternion rotation,Vector3 scale){var go=GameObject.CreatePrimitive(PrimitiveType.Cube);go.name="Landing-only obstacle fixture";go.transform.SetPositionAndRotation(world.RenderBodyPosition(body),rotation);go.transform.localScale=scale;go.GetComponent<MeshRenderer>().enabled=false;Physics.SyncTransforms();return go;}
        Color32[] Capture(string name,bool withHud=false){RenderPipeline.SubmitRenderRequest(world.View,new RenderPipeline.StandardRequest{destination=target});var source=target;if(withHud){compositeMaterial.SetTexture("_Ui",hud);Graphics.Blit(target,composite,compositeMaterial);source=composite;}var old=RenderTexture.active;RenderTexture.active=source;var image=new Texture2D(source.width,source.height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,source.width,source.height),0,0);image.Apply();var pixels=image.GetPixels32();File.WriteAllBytes(Path.Combine(output,name+".png"),image.EncodeToPNG());Destroy(image);RenderTexture.active=old;return pixels;}
        static double P95(List<double> data,double q){data.Sort();return data[(int)((data.Count-1)*q)];}
        IEnumerator Run(){double deadline=Time.realtimeSinceStartupAsDouble+120;while(world.ShipForValidation==null){if(Time.realtimeSinceStartupAsDouble>deadline)throw new TimeoutException();yield return null;}ship=world.ShipForValidation;world.Paused=true;world.AutomaticPlayerStep=false;world.Rig.InputEnabled=false;Check(world.definition.radius==120000,"Assisted landing retains the 120 km-radius gameplay world");
            var parked=ship.Pose;for(int i=0;i<600;i++)ship.Integrate(1f/60,Vector3.one,Vector3.one,true,true);Check(ship.Landed&&(ship.Pose.position-parked.position).Magnitude==0&&Quaternion.Angle(parked.rotation,ship.Pose.rotation)<.001f&&ship.Speed==0,"All thrust, steering, boost and brake inputs leave a landed ship locked in place");Check(!Space(),"Space landing/takeoff rejects requests outside the pilot seat");world.SetShipControl(true);Check(!ship.TryLandingOrTakeoff(),"Paused pilot cannot take off");
            blocker=Cube(parked.position+new Double3(ship.Direction)*40,parked.rotation,new Vector3(15,1,15));Check(!Space()&&ship.Landed&&(ship.Pose.position-parked.position).Magnitude==0,"Overhead obstruction blocks takeoff without moving the parked ship");blocker.SetActive(false);Destroy(blocker);blocker=null;Physics.SyncTransforms();Check(Space(),"Space takes off once overhead clearance is available");Check(!ship.Landed&&ship.AutoFlightActive&&(ship.Pose.position-parked.position).Magnitude==0,"Takeoff starts at the parked pose without a position snap");
            Check(!Space(),"Repeated Space presses cannot restart or reverse an active transition");ship.SetFlightAssistance(false);ship.ToggleRotationLock();Check(ship.FlightAssistEnabled&&!ship.RotationLocked,"Flight mode changes cannot override the automatic transition");
            ship.Integrate(1f/60,Vector3.one,Vector3.one);Check((ship.Pose.position-parked.position).Magnitude>0&&(ship.Pose.position-parked.position).Magnitude<.02,"The first takeoff frame gently lifts rather than jumping to hover height");
            var paused=ship.Pose;ship.Step(1);Check((ship.Pose.position-paused.position).Magnitude==0,"Pausing freezes an active takeoff transition");
            world.SetFirstPerson(false);world.Paused=false;ship.StepUnpiloted(1f/60);world.Paused=true;Check((ship.Pose.position-paused.position).Magnitude>0,"Automatic takeoff continues when the pilot leaves the seat");world.SetShipControl(true);
            FinishTransition();Check(!ship.Landed&&ship.FlightAssistEnabled&&ship.GearDeployed&&Math.Abs((ship.Pose.position-parked.position).Magnitude-80)<.001,"Takeoff smoothly reaches an 80 metre assisted hover");
            var hover=ship.Pose.position;var integration=new List<double>();for(int i=0;i<1200;i++){var timer=System.Diagnostics.Stopwatch.StartNew();ship.Integrate(1f/60,Vector3.zero,Vector3.zero);timer.Stop();integration.Add(timer.Elapsed.TotalMilliseconds);}report.hoverDrift=(ship.Pose.position-hover).Magnitude;Check(report.hoverDrift<.05&&ship.Speed<.05,"Assistance holds altitude and cancels gravity for twenty simulated seconds with no input");
            // Select ordinary dry ground away from the initial base and its plateau blend.
            var surface=new PlanetSurface(world.definition);Vector3 site=world.Base.Offset(new Vector2(0,6500));bool found=false;for(int n=0;n<96;n++){float a=n*2.39996323f;site=world.Base.Offset(new Vector2(Mathf.Cos(a)*6500,Mathf.Sin(a)*6500));if(surface.SampleHeight(site)<world.definition.oceanHeight+40)continue;Place(site,260,Vector3.zero);if(ship.LandingAvailable){found=true;break;}}Check(found,"A full-ship footprint on open dry terrain receives a green landing approval");
            var previews=new List<double>();for(int i=0;i<120;i++){var timer=System.Diagnostics.Stopwatch.StartNew();ship.RefreshLandingPreview(true);timer.Stop();previews.Add(timer.Elapsed.TotalMilliseconds);}
            Place(site,140,Vector3.zero);var level=Quaternion.LookRotation(Vector3.Cross(Vector3.up,site).normalized,site);ship.SetFlightStateForValidation(new SpacePose{position=surface.GetSurfacePositionPrecise(site,140),rotation=level});ship.SetFlightAssistance(true);var before=ship.Pose.position;for(int i=0;i<600;i++)ship.Integrate(1f/60,Vector3.forward,Vector3.zero);Check((ship.Pose.position-before).Magnitude>900&&ship.GroundClearance>60,"Assisted forward cruise moves across the planet while preserving terrain clearance");for(int i=0;i<300;i++)ship.Integrate(1f/60,Vector3.zero,Vector3.zero,true);Check(ship.Speed<1,"Brake and assistance remove drift without repeated counter-thrust");
            Place(site,1000,Vector3.zero);var fall=ship.Pose.position.Magnitude;for(int i=0;i<60;i++)ship.Integrate(1f/60,Vector3.zero,Vector3.zero);Check(!ship.FlightAssistEnabled&&fall-ship.Pose.position.Magnitude>3,"Assistance-off mode retains physical gravity and coasting");ship.SetFlightAssistance(true);ship.ToggleRotationLock();Check(ship.RotationLocked&&!ship.FlightAssistEnabled,"Orbital attitude hold selects unassisted orbital physics");ship.ToggleRotationLock();
            Place(site,701,Vector3.zero);Check(!ship.LandingAvailable&&ship.LandingStatus.Contains("DESCEND"),"Excess altitude produces a red landing rejection");Place(site,260,Vector3.right*181);Check(!ship.LandingAvailable&&ship.LandingStatus.Contains("SLOW"),"Excess speed produces a red landing rejection");
            Vector3 water=Vector3.zero;for(int i=0;i<2048;i++){float z=1-2*(i+.5f)/2048,a=i*2.39996323f,r=Mathf.Sqrt(1-z*z);var d=new Vector3(r*Mathf.Cos(a),z,r*Mathf.Sin(a));if(surface.SampleHeight(d)<world.definition.oceanHeight-10){water=d;break;}}Check(water.sqrMagnitude>0,"Water rejection fixture finds an ocean");Place(water,180,Vector3.zero);Check(!ship.LandingAvailable&&ship.LandingStatus.Contains("WATER"),"Ocean landing is red and cannot be accepted");
            // An obstacle entering an approved corridor must stop an already moving ship.
            Place(site,260,Vector3.zero);Check(Space(),"Open landing approach starts for moving-obstacle validation");ship.Integrate(.05f,Vector3.zero,Vector3.zero);
            blocker=Cube(ship.Pose.position,ship.Pose.rotation,new Vector3(12,20,12));var beforeBlock=ship.Pose;ship.Integrate(.05f,Vector3.zero,Vector3.zero);Check(!ship.AutoFlightActive&&!ship.Landed&&ship.Speed==0&&(ship.Pose.position-beforeBlock.position).Magnitude==0&&ship.LandingStatus.Contains("BLOCKED"),"An obstacle entering during descent stops the assist at its last safe pose");blocker.SetActive(false);Destroy(blocker);blocker=null;Physics.SyncTransforms();
            // Validate actual green/red pixels, not only a status flag.
            Place(site,260,Vector3.zero);target=new RenderTexture(1600,1000,24,RenderTextureFormat.ARGBHalf);target.Create();hud=new RenderTexture(1600,1000,0,RenderTextureFormat.ARGB32);hud.Create();composite=new RenderTexture(1600,1000,0,RenderTextureFormat.ARGB32);composite.Create();compositeMaterial=new Material(Resources.Load<Shader>("MassiveArmy/PlanetUiComposite"));world.View.enabled=false;world.View.targetTexture=target;ship.SetPilotRenderTarget(hud);ship.ShowLandingPreview=false;for(int i=0;i<3;i++)yield return null;var blank=Capture("without-preview");ship.ShowLandingPreview=true;for(int i=0;i<3;i++)yield return null;var green=Capture("landing-green");for(int i=0;i<green.Length;i++)if(green[i].r<blank[i].r-15&&green[i].g>green[i].r*1.2f)report.greenPixels++;Check(report.greenPixels>50,"Green approach curve and full-size landing ghost visibly render through the cockpit camera");Capture("landing-hud",true);
            var display=ship.LandingPosition;blocker=Cube(display,ship.LandingRotation,new Vector3(12,20,12));Check(!Space()&&!ship.Landed&&(ship.Pose.position-display).Magnitude>100,"An obstacle added after a green preview prevents automatic landing");ship.RefreshLandingPreview(true);for(int i=0;i<2;i++)yield return null;var red=Capture("landing-red");for(int i=0;i<red.Length;i++)if(red[i].g<blank[i].g-15&&red[i].r>red[i].g*1.2f)report.redPixels++;Check(report.redPixels>50&&!ship.LandingAvailable,"Blocked approach visibly changes the landing path and ghost to red");blocker.SetActive(false);Destroy(blocker);blocker=null;Physics.SyncTransforms();ship.RefreshLandingPreview(true);var exact=ship.LandingPosition;var exactRotation=ship.LandingRotation;Check(Space(),"Space accepts a green destination after the obstacle is removed");Check(ship.AutoFlightActive&&!ship.Landed&&(ship.Pose.position-exact).Magnitude>100,"Landing begins above the approved site without snapping to the ground");
            var beginning=ship.Pose;ship.Integrate(1f/60,Vector3.one,Vector3.one);Check((ship.Pose.position-beginning.position).Magnitude<.05&&Quaternion.Angle(beginning.rotation,ship.Pose.rotation)<.05,"Landing begins with smooth translation and rotation");
            FinishTransition();report.landingError=(ship.Pose.position-exact).Magnitude;Check(ship.Landed&&report.landingError<1e-8&&Quaternion.Angle(ship.Pose.rotation,exactRotation)<.001f&&ship.Speed==0,"Landing uses the exact displayed double-precision position and orientation and stops all motion");var locked=ship.Pose;for(int i=0;i<600;i++)ship.Integrate(1f/60,Vector3.one,Vector3.one,boost:true);Check((ship.Pose.position-locked.position).Magnitude==0&&Quaternion.Angle(ship.Pose.rotation,locked.rotation)<.001f,"The landed pose remains locked despite cockpit movement inputs");for(int i=0;i<2;i++)yield return null;Check(world.View.transform.position==Vector3.zero,"Landing retains the camera-at-zero floating origin");Check(Space(),"A later Space press releases the ground lock and takes off again");
            Place(site,260,Vector3.zero);world.definition.Edits.AddCrater(site,60);world.TerrainChanged();ship.RefreshLandingPreview(true);Check(!ship.LandingAvailable,"A strongly uneven crater footprint cannot receive a green landing approval");
            report.assistMedianMs=P95(integration,.5);report.assistP95Ms=P95(integration,.95);report.previewMedianMs=P95(previews,.5);report.previewP95Ms=P95(previews,.95);world.AutomaticPlayerStep=true;
        }
        void OnDestroy(){if(world!=null)world.AutomaticPlayerStep=true;if(blocker!=null)Destroy(blocker);foreach(var rt in new[]{target,hud,composite})if(rt!=null){rt.Release();Destroy(rt);}if(compositeMaterial!=null)Destroy(compositeMaterial);}
    }
}
